import{_ as r,o as a,c as e,ag as d}from"./chunks/framework.BjY7aUvS.js";const g=JSON.parse('{"title":"全家反诈体检 · 国家反诈中心 + 96110 + 一证通查","description":"全家反诈体检四步：国家反诈中心 APP 开预警、96110/12381 两个预警渠道、一证通查清查名下电话卡、高发骗局速查表。","frontmatter":{"title":"全家反诈体检 · 国家反诈中心 + 96110 + 一证通查","issuer":"公安部（刑事侦查局） / 工业和信息化部","source_tier":"一级来源","version":"—","published":"—","source_url":"https://getsimnum.caict.ac.cn/","status":"现行服务","tags":["官方查询","反诈",96110,"一证通查","国家反诈中心","家庭安全"],"type":"查询页","reviewed":false,"description":"全家反诈体检四步：国家反诈中心 APP 开预警、96110/12381 两个预警渠道、一证通查清查名下电话卡、高发骗局速查表。"},"headers":[],"relativePath":"query/anti-fraud.md","filePath":"query/anti-fraud.md"}'),o={name:"query/anti-fraud.md"};function n(s,t,h,l,i,c){return a(),e("div",null,[...t[0]||(t[0]=[d('<h1 id="全家反诈体检-·-国家反诈中心-96110-一证通查" tabindex="-1">全家反诈体检 · 国家反诈中心 + 96110 + 一证通查 <a class="header-anchor" href="#全家反诈体检-·-国家反诈中心-96110-一证通查" aria-label="Permalink to &quot;全家反诈体检 · 国家反诈中心 + 96110 + 一证通查&quot;">​</a></h1><div class="warning custom-block"><p class="custom-block-title">待核验</p><p>本页由 AI 依据公安部、工信部公开宣传口径整理；&quot;一证通查&quot;入口已浏览器核验可达，APP 与热线功能以官方发布为准。</p></div><div class="danger custom-block"><p class="custom-block-title">使用须知</p><p>电信诈骗是当前家庭财产损失最大、最高频的坑。本页四步做完约 15 分钟，<strong>建议每个家庭每年做一次</strong>——尤其给父母做。</p></div><h2 id="速览卡-三道防线-一个底查" tabindex="-1">速览卡（三道防线 + 一个底查） <a class="header-anchor" href="#速览卡-三道防线-一个底查" aria-label="Permalink to &quot;速览卡（三道防线 + 一个底查）&quot;">​</a></h2><table tabindex="0"><thead><tr><th>防线</th><th>是什么</th></tr></thead><tbody><tr><td><strong>国家反诈中心 APP</strong>（公安部刑侦局）</td><td>开启来电/短信/APP 风险预警——诈骗电话打进来会拦截提醒</td></tr><tr><td><strong>96110</strong></td><td>反诈预警劝阻专线——<strong>这个号码打来的务必接</strong>，是警察在阻拦你转账</td></tr><tr><td><strong>12381</strong></td><td>工信部涉诈预警劝阻短信——收到即高危</td></tr><tr><td><strong>一证通查</strong></td><td>查<strong>名下</strong>到底有几张电话卡——防止被冒名办卡用于诈骗</td></tr></tbody></table><h2 id="四步行动清单" tabindex="-1">四步行动清单 <a class="header-anchor" href="#四步行动清单" aria-label="Permalink to &quot;四步行动清单&quot;">​</a></h2><table tabindex="0"><thead><tr><th>步骤</th><th>怎么做</th><th>出处</th></tr></thead><tbody><tr><td>1</td><td>全家手机安装<strong>国家反诈中心 APP</strong>（官方应用商店，开发者&quot;公安部刑事侦查局&quot;），开启来电预警权限</td><td>公安部发布口径</td></tr><tr><td>2</td><td>告诉父母：<strong>96110 打来的必须接</strong>；收到 <strong>12381</strong> 预警短信立即停手核实</td><td>工信部/公安部</td></tr><tr><td>3</td><td><a href="https://getsimnum.caict.ac.cn/" target="_blank" rel="noreferrer">一证通查</a>（已核验可达）：凭身份证查名下电话卡数量——多出来的卡立即去运营商销户（互联网账号查询为 2.0 服务，域名 getaccount.caict.ac.cn 经人工浏览器访问确认有效）</td><td><a href="https://getsimnum.caict.ac.cn/" target="_blank" rel="noreferrer">信通院平台</a></td></tr><tr><td>4</td><td>给父母做一次&quot;骗局考试&quot;（见下表），让他们复述&quot;三个凡是&quot;</td><td>公安部宣传口径</td></tr></tbody></table><h2 id="高发骗局速查表" tabindex="-1">高发骗局速查表 <a class="header-anchor" href="#高发骗局速查表" aria-label="Permalink to &quot;高发骗局速查表&quot;">​</a></h2><table tabindex="0"><thead><tr><th>骗局</th><th>一句话拆解</th></tr></thead><tbody><tr><td>冒充公检法</td><td>真警察<strong>不会</strong>电话办案、不会要你转账到&quot;安全账户&quot;、不会让你保密</td></tr><tr><td>刷单返利</td><td>先给甜头后宰杀，所有刷单都是诈骗</td></tr><tr><td>虚假投资理财（杀猪盘）</td><td>网友/导师带你&quot;稳赚&quot;的平台 = 你看到的数字都是画的</td></tr><tr><td>冒充电商客服退款</td><td>绕开平台私下&quot;退款理赔&quot;的都是诈骗，退款只走原平台</td></tr><tr><td>冒充领导/熟人</td><td>换号、AI 合成声音——当面或回拨本人常用号码核实</td></tr><tr><td>AI 换脸视频通话</td><td>视频也能造——<strong>看脸不如验证</strong>：让对方做指定动作、问只有本人知道的事</td></tr></tbody></table><p><strong>&quot;三个凡是&quot;铁律</strong>（教给父母）：凡是要求<strong>转账到安全账户</strong>的都是诈骗；凡是要求<strong>屏幕共享/提供验证码</strong>的都是诈骗；凡是<strong>网上认识就带你投资</strong>的都是诈骗。</p><h2 id="万一已经中招" tabindex="-1">万一已经中招 <a class="header-anchor" href="#万一已经中招" aria-label="Permalink to &quot;万一已经中招&quot;">​</a></h2><table tabindex="0"><thead><tr><th>时点</th><th>动作</th></tr></thead><tbody><tr><td>立即</td><td>拨打 <strong>110</strong> 报警 + 银行客服挂失止付——<strong>黄金 30 分钟</strong>内报警有止付追回可能</td></tr><tr><td>同时</td><td>保留转账凭证、聊天记录、对方账号</td></tr><tr><td>事后</td><td>被骗信息在[国家反诈中心 APP]内一键举报；涉诈网页/账号到 <a href="/SageRelay/query/complaint-channels.html">12377</a> 举报</td></tr></tbody></table><h2 id="相关页面" tabindex="-1">相关页面 <a class="header-anchor" href="#相关页面" aria-label="Permalink to &quot;相关页面&quot;">​</a></h2><ul><li>网络诈骗信息举报：<a href="/SageRelay/query/complaint-channels.html">投诉举报渠道全景</a> · 商家类纠纷走 <a href="/SageRelay/query/samr-12315.html">12315</a></li><li>老人照护：<a href="/SageRelay/query/elder-care.html">养老地图</a>（养老诈骗三件套）· <a href="/SageRelay/query/health-food.html">保健食品查询</a></li></ul><h2 id="溯源" tabindex="-1">溯源 <a class="header-anchor" href="#溯源" aria-label="Permalink to &quot;溯源&quot;">​</a></h2><table tabindex="0"><thead><tr><th>字段</th><th>内容</th></tr></thead><tbody><tr><td>主管</td><td>公安部刑事侦查局（反诈中心/96110）、工业和信息化部（12381/一证通查）</td></tr><tr><td>入口</td><td><a href="https://getsimnum.caict.ac.cn/" target="_blank" rel="noreferrer">一证通查</a>（已核验可达）· 国家反诈中心 APP · 96110 · 12381</td></tr></tbody></table>',16)])])}const b=r(o,[["render",n]]);export{g as __pageData,b as default};
